def correct_bracketing(brackets: str):
    if not brackets:
        return True

    open_brackets = 0
    close_brackets = 0

    for char in brackets:
        if char == '(':
            open_brackets += 1
        elif char == ')':
            close_brackets += 1

    if open_brackets != close_brackets:
